export function analyzeConcept(content) {
  const hasCodeKeywords = /(const|let|function|class|import|```)/i.test(content.explanation);
  if (hasCodeKeywords) {
    return {
      conceptType: 'code',
      uiStrategy: 'code-split'
    };
  }
  return { conceptType: 'standard', uiStrategy: 'standard' };
} 
