// Updating user Elo based on answer correctness
function updateElo(userElo, questionElo, isCorrect) {
  const kFactor = 32;
  const expectedScore = 1 / (1 + Math.pow(10, (questionElo - userElo) / 400));
  const actualScore = isCorrect ? 1 : 0;
  return userElo + kFactor * (actualScore - expectedScore);
}
```

